import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"診断パネルを読む","description":"","frontmatter":{},"headers":[],"relativePath":"guides/debugging.md","filePath":"guides/debugging.md","lastUpdated":1793464466000}`),a={name:`guides/debugging.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="診断パネルを読む" tabindex="-1">診断パネルを読む <a class="header-anchor" href="#診断パネルを読む" aria-label="Permalink to “診断パネルを読む”">​</a></h1><p>「なぜ表示されたか」「なぜ表示されないか」を、実際に操作しているブラウザで調べます。サイトの編集権限が必要です。</p><h2 id="開き方" tabindex="-1">開き方 <a class="header-anchor" href="#開き方" aria-label="Permalink to “開き方”">​</a></h2><p>管理画面の「動作確認」で対象URLを入力し、実サイトで診断を開始します。対象サイトのSDKと管理画面を開いたままにしてください。</p><p>サイト側に一時的なパネルを表示します。ブラウザ拡張は不要です。認可はサイトとOriginを限定し、15分間有効です。管理者トークンやパスキー情報をサイトへ渡しません。</p><h2 id="見られるもの" tabindex="-1">見られるもの <a class="header-anchor" href="#見られるもの" aria-label="Permalink to “見られるもの”">​</a></h2><table tabindex="0"><thead><tr><th>タブ</th><th>内容</th></tr></thead><tbody><tr><td>現在の状態</td><td>同意・計測・表示時間・現在のページ等</td></tr><tr><td>閲覧・行動</td><td>このブラウザで観測したページ、取得元、追加イベントや状態</td></tr><tr><td>判定履歴</td><td>判断API要求・応答、Jev用state/questions、判定値、確定条件と表示制約</td></tr></tbody></table><p>履歴は診断用にサーバーへ保存しません。通常のAPI要求を観察し、パネルを開いたからといって追加のJev問い合わせをしません。診断も同意を迂回しません。</p><h2 id="表示されないときの読み方" tabindex="-1">表示されないときの読み方 <a class="header-anchor" href="#表示されないときの読み方" aria-label="Permalink to “表示されないときの読み方”">​</a></h2><ul><li><strong>メタデータ送信が未承認</strong>：サイト設定で送信を有効にしたか確認。</li><li><strong>有効閲覧が不足</strong>：表示時間と件数を確認。背景タブの時間は表示中の時間へ含めない。</li><li><strong>対象ページ外</strong>：収集範囲と施策の表示対象をそれぞれ確認。</li><li><strong>表示済み・閉じた状態</strong>：このブラウザ内の上限と状態を確認。</li><li><strong>確定状態が不明</strong>：除外factを指定したならfalse/trueを明示して連携。</li><li><strong>判定値が足りない</strong>：質問と閾値を確認。値を購入率として読まない。</li><li><strong>モデルエラー・費用上限</strong>：運用者がキー・モデル・上限を確認。</li></ul><h2 id="previewのテスト値" tabindex="-1">Previewのテスト値 <a class="header-anchor" href="#previewのテスト値" aria-label="Permalink to “Previewのテスト値”">​</a></h2><p>スタブ環境では「固定のテスト値で判定」「Jevへ未送信」と区別します。ここでの0.95は実モデルの出力ではありません。利用量や速度の実測として扱いません。</p><h2 id="共有するとき" tabindex="-1">共有するとき <a class="header-anchor" href="#共有するとき" aria-label="Permalink to “共有するとき”">​</a></h2><p>要求や画面にページ情報・行動情報が含まれます。スクリーンショットやJSONを共有する前に、個人情報・機密・認証情報が含まれていないか確認してください。通常のIssuesへ実閲覧履歴をそのまま貼らないでください。</p><p>終了ボタンで診断を閉じます。ユーザー停止やサイト権限の取消でも認可を失います。単なるログアウトだけで、発行済みの診断認可を個別に消去する方式ではありません。</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};